sys_script_include.script:
var BasesUtils = Class.create();
BasesUtils.prototype = {
    initialize: function() {
    },
	refQualBases: function(){
		var userRegistrate = false;
		var basesNotToShow = [];
		var grBases = new GlideRecord("x_1584312_bases_base");
		grBases.query();

		while(grBases.next()){
			var grRegistrations = new GlideRecord("x_1584312_bases_registration");
			grRegistrations.addEncodedQuery("base=" + grBases.sys_id.toString() + "^stateIN2,3");
			grRegistrations.query();

			var countRegistrations = 0;
			while(grRegistrations.next()){
				countRegistrations++;

				if(grRegistrations.opened_by.sys_id.toString() == gs.getUserID().toString()){
					userRegistrate = true;
				}
			}
			if(countRegistrations >= grBases.max_capacity){
				basesNotToShow.push(grBases.sys_id.toString());
			}
		}

		basesToShow = [];

		grBases.query(); 
        while(grBases.next()) {
            if (basesNotToShow.indexOf(grBases.sys_id.toString()) == -1 && userRegistrate == false) {
                basesToShow.push(grBases.sys_id.toString());
            }
        }

		return "sys_idIN" + basesToShow.join(",");
	},

	refQualOpenBases: function(){
		var basesNotToShow = [];
		var grBases = new GlideRecord("x_1584312_bases_base");
		grBases.query();

		while(grBases.next()){
			var grRegistrations = new GlideRecord("x_1584312_bases_registration");
			grRegistrations.addEncodedQuery("base=" + grBases.sys_id.toString() + "^stateIN2,3");
			grRegistrations.query();

			var countRegistrations = 0;
			while(grRegistrations.next()){
				countRegistrations++;
			}
			if(countRegistrations >= grBases.max_capacity){
				basesNotToShow.push(grBases.sys_id.toString());
			}
		}

		basesToShow = [];

		grBases.query(); 
        while(grBases.next()) {
            if (basesNotToShow.indexOf(grBases.sys_id.toString()) == -1) {
                basesToShow.push(grBases.sys_id.toString());
            }
        }

		return "sys_idIN" + basesToShow.join(",");
	},

	refQualGroupManager: function(){
		var usersInGroup = [];
		var grGroup = new GlideRecord("sys_user_grmember");
		grGroup.addEncodedQuery("group=81556e378373121037bab6cfeeaad383");
		grGroup.query();
		while(grGroup.next()){
			usersInGroup.push(grGroup.user.sys_id.toString());
		}
		gs.info("Sys Ids encontrados:" + usersInGroup);

		return "sys_idIN" + usersInGroup.join(",");

	},	


	refQualGroupUser: function() {
    var usersInGroup = [];
    var grGroup = new GlideRecord("sys_user_grmember");
    grGroup.addEncodedQuery("group=8a9566778373121037bab6cfeeaad39c"); 
    grGroup.query();

    while (grGroup.next()) {
        var grRegistrations = new GlideRecord("x_1584312_bases_registration");
        grRegistrations.addEncodedQuery("opened_by=" + grGroup.user.sys_id.toString() + "^stateIN2,3"); 
        grRegistrations.query();

        if (grRegistrations.getRowCount() == 0) {
            usersInGroup.push(grGroup.user.sys_id.toString());
        }
    }

    gs.info("Sys Ids encontrados: " + usersInGroup.join(","));

    return "sys_idIN" + usersInGroup.join(",");	
	},

    type: 'BasesUtils'
};
